def compute(vars):
    total_shares = vars["v1"]
    open_market_shares = vars["v2"]

    if total_shares == 0:
        return None

    percentage = (open_market_shares / total_shares) * 100

    return {
        "value": percentage,
        "trace": {
            "total_shares": total_shares,
            "open_market_shares": open_market_shares,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
